%[text] # 江苏省工商业分时电价下独立储能日前套利优化模型
%[text] 课程名称：《储能优化配置与调度技术》课程设计（随堂演示脚本 02）
%[text] ## 0. 教学目标与独立储能套利数学模型
%[text] **教学目标**：
%[text] - 掌握 YALMIP 建模工具箱中连续变量（|sdpvar|）、二进制变量（|binvar|）、约束集合（|Constraints|）与求解器配置（|sdpsettings|）的标准语法；
%[text] - 建立以无量纲荷电状态 $\\mathrm{SoC}\_t$ 为直接决策变量的独立储能日前分时电价（TOU）套利混合整数线性规划（MILP）模型；
%[text] - 对比验证正电价下“含充放电互斥二进制变量 $u\_t^{\\mathrm{ch}}$”与“松弛二进制变量（纯 LP）”解的等价性，并绘制符合《中国电机工程学报》规范的双轴运行曲线。 \
%[text] **数学模型**：
%[text] **1) 目标函数（最大化全天电价套利净收益）**：
%[text]{"align":"center"} $\\max \\sum\_{t=1}^{T} \\lambda\_t \\left( P\_t^{\\mathrm{dis}} - P\_t^{\\mathrm{ch}} \\right) \\Delta t \\Leftrightarrow \\min \\sum\_{t=1}^{T} \\lambda\_t \\left( P\_t^{\\mathrm{ch}} - P\_t^{\\mathrm{dis}} \\right) \\Delta t$
%[text] **2) 荷电状态（SoC）跨时段耦合差分方程**（注意分母除以额定容量 $E\_{\\mathrm{rated}}$ 以保证量纲一致）：
%[text]{"align":"center"} $\\mathrm{SoC}\_t = \\mathrm{SoC}\_{t-1} + \\frac{\\eta\_{\\mathrm{ch}} P\_t^{\\mathrm{ch}} \\Delta t}{E\_{\\mathrm{rated}}} - \\frac{P\_t^{\\mathrm{dis}} \\Delta t}{\\eta\_{\\mathrm{dis}} E\_{\\mathrm{rated}}}, \\quad \\forall t \\in \\{1, 2, \\dots, T\\}$
%[text] **3) 荷电状态上下限、首尾周期平衡与充放电互斥约束**：
%[text]{"align":"center"} $\\mathrm{SoC}\_{\\min} \\le \\mathrm{SoC}\_t \\le \\mathrm{SoC}\_{\\max}, \\quad \\mathrm{SoC}\_T = \\mathrm{SoC}\_0$
%[text]{"align":"center"} $0 \\le P\_t^{\\mathrm{ch}} \\le u\_t^{\\mathrm{ch}} P\_{\\mathrm{rated}}, \\quad 0 \\le P\_t^{\\mathrm{dis}} \\le \\left(1 - u\_t^{\\mathrm{ch}}\\right) P\_{\\mathrm{rated}}, \\quad u\_t^{\\mathrm{ch}} \\in \\{0, 1\\}$
clear; clc; close all;
yalmip('clear');
%%
%[text] ## 1. 加载江苏省分时电价数据与储能系统参数
%[text] ## 1.1 自动检测并加载分时电价数据包
if ~exist('profiles_24h.mat', 'file')
    rel_case_dir = fullfile(fileparts(mfilename('fullpath')), '..', 'cases');
    if exist(rel_case_dir, 'dir')
        addpath(rel_case_dir);
    elseif exist(fullfile(pwd, 'ESS-Course-Materials', 'cases'), 'dir')
        addpath(fullfile(pwd, 'ESS-Course-Materials', 'cases'));
    else
        case_dir = uigetdir(pwd, '请选择教学资源库中的 cases 文件夹路径');
        addpath(case_dir);
    end
end
load('profiles_24h.mat');
%[text] ## 1.2 储能电站技术参数设置
%[text] 给定独立储能电站额定功率 $P\_{\\mathrm{rated}} = 2.0\\;\\mathrm{MW}$，额定容量 $E\_{\\mathrm{rated}} = 2.0\\;\\mathrm{MWh}$，充电效率 $\\eta\_{\\mathrm{ch}} = 0.90$，放电效率 $\\eta\_{\\mathrm{dis}} = 0.95$。
P_rated = 2.0;    % 额定功率 P_rated (MW)
E_rated = 2.0;    % 额定能量容量 E_rated (MWh)
eta_ch  = 0.90;   % 充电效率 \eta_ch
eta_dis = 0.95;   % 放电效率 \eta_dis
SoC_0   = 0.50;   % 初始与末态荷电状态 SoC_0
SoC_min = 0.10;   % 最小荷电状态 SoC_min
SoC_max = 1.00;   % 最大荷电状态 SoC_max
dt      = 1.0;    % 调度时间步长 \Delta t (h)
%%
%[text] ## 2. 声明 YALMIP 决策变量
%[text] 直接以无量纲荷电状态 $\\mathrm{SoC}\_t \\in \[0, 1\]$ 作为状态决策变量：
P_ch  = sdpvar(T, 1, 'full'); % 充电功率 P_t^{ch} (MW)
P_dis = sdpvar(T, 1, 'full'); % 放电功率 P_t^{dis} (MW)
SoC   = sdpvar(T, 1, 'full'); % 荷电状态 SoC_t
u_ch  = binvar(T, 1, 'full'); % 充电状态二进制变量 u_t^{ch} \in {0,1}
%%
%[text] ## 3. 构建储能运行约束条件集合
Constraints = [];

% 充放电功率上下限与互斥逻辑约束
Constraints = [Constraints, 0 <= P_ch  <= u_ch * P_rated];
Constraints = [Constraints, 0 <= P_dis <= (1 - u_ch) * P_rated];

% 荷电状态安全边界与日周期首尾平衡约束
Constraints = [Constraints, SoC_min <= SoC <= SoC_max];
Constraints = [Constraints, SoC(T) == SoC_0];

% 时序荷电状态递推差分方程
for t = 1:T
    if t == 1
        soc_prev = SoC_0;
    else
        soc_prev = SoC(t - 1);
    end
    Constraints = [Constraints, SoC(t) == soc_prev + ...
        (eta_ch * P_ch(t) * dt) / E_rated - (P_dis(t) * dt) / (eta_dis * E_rated)];
end
%%
%[text] ## 4. 定义目标函数并调用 MATLAB 原生求解器求解
%[text] YALMIP 默认求解最小化问题，因此最大化套利净收益 $R\_{\\mathrm{arb}}$ 等价于最小化 $-R\_{\\mathrm{arb}}$。任务二 MILP 模型默认调用 MATLAB Optimization Toolbox 原生 `intlinprog` 求解（调用前将内置 `optim` 目录置顶，避免被路径中 MOSEK 的同名兼容函数覆盖）。
Total_Revenue = sum(price_MWh .* (P_dis - P_ch) * dt);
Objective     = -Total_Revenue;

native_optim_dir = fullfile(matlabroot, 'toolbox', 'optim', 'optim');
if exist(native_optim_dir, 'dir')
    addpath(native_optim_dir, '-begin');
end
solver_name = 'intlinprog';
ops = sdpsettings('solver', solver_name, 'verbose', 1);
sol = optimize(Constraints, Objective, ops); %[output:9166c830]

if sol.problem == 0 %[output:group:70d80c20]
    fprintf('求解成功 (求解器: %s)，全天最大套利净收益: %.2f 元\n', solver_name, value(Total_Revenue)); %[output:8e855b4d]
else
    error('求解失败: %s', yalmiperror(sol.problem));
end %[output:group:70d80c20]
%%
%[text] ## 5. 绘制符合《中国电机工程学报》规范的储能套利运行曲线
%[text] 规范要求：中文采用宋体，西文与数字采用 Times New Roman，物理量变量符号采用斜体，下标说明与单位采用正体。
P_net_val = value(P_dis - P_ch);
SoC_val   = [SoC_0; value(SoC)] * 100; % 转换为百分比 (%)

fig1 = figure('Name', '独立储能日前分时电价套利曲线', 'Color', 'w', 'Position', [120, 100, 700, 500]); %[output:2d2791c9]
if isprop(fig1, 'Theme'), theme(fig1, 'light'); end %[output:2d2791c9]

% 子图 (a)：充放电功率与分时电价
subplot(2, 1, 1); %[output:2d2791c9]
yyaxis left; %[output:2d2791c9]
b_handle = bar(1:T, P_net_val, 0.62, 'FaceColor', [0.16, 0.44, 0.69], 'EdgeColor', 'none'); %[output:2d2791c9]
ylabel('\fontname{宋体}净放电功率 \fontname{Times New Roman}{\itP}_{\rm{net}}\rm{/MW}', 'FontSize', 11.5, 'Interpreter', 'tex'); %[output:2d2791c9]
ylim([-2.5, 3.2]); %[output:2d2791c9]
ax1 = gca;
ax1.YAxis(1).Color = [0.10, 0.30, 0.55]; %[output:2d2791c9]

yyaxis right; %[output:2d2791c9]
s_handle = stairs(1:T, price_kWh, '-r', 'LineWidth', 1.8); %[output:2d2791c9]
ylabel('\fontname{宋体}分时电价 \fontname{Times New Roman}{\itc}_{\itt}\rm{/(\fontname{宋体}元\fontname{Times New Roman}\cdot(kW\cdot h)^{-1})}', ... %[output:2d2791c9]
    'FontSize', 11.5, 'Interpreter', 'tex'); %[output:2d2791c9]
ylim([0.1, 1.55]); %[output:2d2791c9]
ax1.YAxis(2).Color = [0.80, 0.10, 0.10]; %[output:2d2791c9]

set(gca, 'Color', 'w', 'XColor', 'k', 'FontName', 'Times New Roman', 'FontSize', 10.5, 'LineWidth', 1.0, ... %[output:2d2791c9]
    'Box', 'on', 'TickDir', 'in', 'XTick', 0:4:24, 'GridLineStyle', '--', 'GridAlpha', 0.3, 'GridColor', [0.4, 0.4, 0.4]); %[output:2d2791c9]
xlim([0.5, 24.5]); %[output:2d2791c9]
xlabel('\fontname{宋体}时间 \fontname{Times New Roman}{\itt}\rm{/h}', 'FontSize', 11.5, 'Color', 'k', 'Interpreter', 'tex'); %[output:2d2791c9]
title(sprintf('\\fontname{宋体}(a) 储能充放电功率与分时电价曲线 (日最大净收益: \\fontname{Times New Roman}%.2f \\fontname{宋体}元)', ... %[output:2d2791c9]
    value(Total_Revenue)), 'FontSize', 11.5, 'FontWeight', 'normal', 'Color', 'k', 'Interpreter', 'tex'); %[output:2d2791c9]
leg1 = legend([b_handle, s_handle], {'\fontname{宋体}净放电功率 \fontname{Times New Roman}{\itP}_{\rm{dis}}-{\itP}_{\rm{ch}}', ... %[output:2d2791c9]
    '\fontname{宋体}分时电价 \fontname{Times New Roman}{\itc}_{\itt}'}, ... %[output:2d2791c9]
    'Location', 'north', 'Orientation', 'horizontal', 'FontSize', 10, 'Interpreter', 'tex', 'Box', 'on'); %[output:2d2791c9]
set(leg1, 'Color', 'w', 'TextColor', 'k', 'EdgeColor', 'k'); %[output:2d2791c9]
grid on; %[output:2d2791c9]

% 子图 (b)：储能荷电状态 SoC 时序轨迹
subplot(2, 1, 2); %[output:2d2791c9]
plot(0:T, SoC_val, '-bo', 'LineWidth', 1.6, 'MarkerSize', 5, 'MarkerFaceColor', [0.16, 0.44, 0.69], 'Color', [0.16, 0.44, 0.69]); %[output:2d2791c9]
hold on; %[output:2d2791c9]
yline(SoC_min * 100, '--k', 'LineWidth', 1.1); %[output:2d2791c9]
yline(SoC_max * 100, '--r', 'LineWidth', 1.1); %[output:2d2791c9]
set(gca, 'Color', 'w', 'XColor', 'k', 'YColor', 'k', 'FontName', 'Times New Roman', 'FontSize', 10.5, 'LineWidth', 1.0, ... %[output:2d2791c9]
    'Box', 'on', 'TickDir', 'in', 'XTick', 0:4:24, 'GridLineStyle', '--', 'GridAlpha', 0.3, 'GridColor', [0.4, 0.4, 0.4]); %[output:2d2791c9]
xlim([0, 24]); %[output:2d2791c9]
ylim([0, 128]); %[output:2d2791c9]
xlabel('\fontname{宋体}时间 \fontname{Times New Roman}{\itt}\rm{/h}', 'FontSize', 11.5, 'Color', 'k', 'Interpreter', 'tex'); %[output:2d2791c9]
ylabel('\fontname{宋体}荷电状态 \fontname{Times New Roman}\rm{SoC}/%', 'FontSize', 11.5, 'Color', 'k', 'Interpreter', 'tex'); %[output:2d2791c9]
title('\fontname{宋体}(b) 储能电站荷电状态 \fontname{Times New Roman}\rm{SoC} \fontname{宋体}时序变化轨迹', ... %[output:2d2791c9]
    'FontSize', 11.5, 'FontWeight', 'normal', 'Color', 'k', 'Interpreter', 'tex'); %[output:2d2791c9]
leg2 = legend({'\fontname{宋体}荷电状态 \fontname{Times New Roman}\rm{SoC}_{\itt}', ... %[output:2d2791c9]
    '\fontname{宋体}下限 \fontname{Times New Roman}\rm{SoC}_{\rm{min}}', ... %[output:2d2791c9]
    '\fontname{宋体}上限 \fontname{Times New Roman}\rm{SoC}_{\rm{max}}'}, ... %[output:2d2791c9]
    'Location', 'north', 'Orientation', 'horizontal', 'FontSize', 10, 'Interpreter', 'tex', 'Box', 'on'); %[output:2d2791c9]
set(leg2, 'Color', 'w', 'TextColor', 'k', 'EdgeColor', 'k'); %[output:2d2791c9]
grid on; %[output:2d2791c9]

% 默认自动导出高质量白底 PNG (600 dpi)、矢量 PDF 与 MATLAB 源文件 FIG
exportgraphics(fig1, 'Fig_Task2_SingleNode_Arbitrage.png', 'Resolution', 600, 'BackgroundColor', 'white'); %[output:2d2791c9]
exportgraphics(fig1, 'Fig_Task2_SingleNode_Arbitrage.pdf', 'ContentType', 'vector', 'BackgroundColor', 'white'); %[output:2d2791c9]
savefig(fig1, 'Fig_Task2_SingleNode_Arbitrage.fig');

